main.script:
document.addEventListener('DOMContentLoaded', function() {
    var filterBtns = document.querySelectorAll('.ins-res-filter-btn');
    var cards = document.querySelectorAll('.ins-res-card');
    var searchInput = document.getElementById('ins_resource_search');

    function applyFilter() {
        var activeBtn = document.querySelector('.ins-res-filter-btn.active');
        var cat = activeBtn ? activeBtn.getAttribute('data-filter') : 'all';
        var q = searchInput ? searchInput.value.toLowerCase().trim() : '';

        cards.forEach(function(card) {
            var cardCat = card.getAttribute('data-category');
            var cardText = card.textContent.toLowerCase();
            var matchesCat = (cat === 'all' || cardCat === cat);
            var matchesSearch = (!q || cardText.indexOf(q) !== -1);
            if (matchesCat && matchesSearch) {
                card.classList.remove('d-none');
            } else {
                card.classList.add('d-none');
            }
        });
    }

    if (filterBtns.length) {
        filterBtns.forEach(function(btn) {
            btn.addEventListener('click', function() {
                filterBtns.forEach(function(b) { b.classList.remove('active'); });
                this.classList.add('active');
                applyFilter();
            });
        });
    }

    if (searchInput) {
        searchInput.addEventListener('input', applyFilter);
    }
});

div.script:
document.addEventListener('DOMContentLoaded', function() {
    var currentBilling = 'monthly';
    var billingBtns = document.querySelectorAll('.ins-billing-btn');
    var tierPrices = document.querySelectorAll('.ins-tier-price');
    var tierPeriods = document.querySelectorAll('.ins-tier-period');
    var modChecks = document.querySelectorAll('.ins-mod-check');
    var totalVndEl = document.getElementById('ins-pricing-total-vnd');
    var totalUsdEl = document.getElementById('ins-pricing-total-usd');
    var periodEl = document.querySelector('.ins-dyn-period');
    var savingsEl = document.querySelector('.ins-dyn-savings');
    var paybackEl = document.querySelector('.ins-payback-label');
    var progressFill = document.querySelector('.ins-roi-progress-fill');
    var tcoMultEl = document.querySelector('.ins-roi-tco-mult');

    function updatePricing() {
        var mult = (currentBilling === 'annual') ? 0.8 : 1.0;
        var sum = 0;
        modChecks.forEach(function(chk) {
            if (chk.checked) {
                var p = parseFloat(chk.getAttribute('data-price-month') || '0');
                sum += p;
            }
        });
        var monthlyCalc = sum * mult;
        var usdCalc = Math.round(monthlyCalc / 25000);
        if (totalVndEl) {
            totalVndEl.textContent = '₫' + monthlyCalc.toLocaleString('vi-VN');
        }
        if (totalUsdEl) {
            totalUsdEl.textContent = '$' + usdCalc.toLocaleString('en-US') + (currentBilling === 'annual' ? ' USD/mo (billed annually)' : ' USD/mo');
        }
        if (periodEl) {
            periodEl.textContent = currentBilling === 'annual' ? '/ Tháng (Trả theo năm)' : '/ Tháng';
        }
        tierPrices.forEach(function(el) {
            var val = el.getAttribute(currentBilling === 'annual' ? 'data-annual' : 'data-monthly');
            if (val) el.textContent = val;
        });
        tierPeriods.forEach(function(el) {
            el.textContent = currentBilling === 'annual' ? ' / Tháng (Trả năm)' : ' / Tháng';
        });

        var annualCost = monthlyCalc * 12;
        var annualSavings = Math.max(annualCost * 3.8, 850000000);
        if (savingsEl) {
            savingsEl.textContent = '₫' + Math.round(annualSavings).toLocaleString('vi-VN') + ' VNĐ';
        }
        var paybackMonths = monthlyCalc > 0 ? (2.2 + (monthlyCalc / 50000000) * 1.4).toFixed(1) : '0';
        if (paybackEl) {
            paybackEl.innerHTML = 'Điểm hòa vốn: <strong>' + paybackMonths + ' Tháng</strong>';
        }
        if (progressFill) {
            var pct = Math.min(Math.max(Math.round((5 - parseFloat(paybackMonths)) / 5 * 100), 20), 95);
            progressFill.style.width = pct + '%';
        }
        if (tcoMultEl) {
            tcoMultEl.textContent = (annualCost > 0 ? (annualSavings / annualCost).toFixed(1) : '4.4') + 'x TCO';
        }
    }

    billingBtns.forEach(function(btn) {
        btn.addEventListener('click', function() {
            var b = this.getAttribute('data-billing');
            if (b === currentBilling) return;
            currentBilling = b;
            billingBtns.forEach(function(el) {
                if (el.getAttribute('data-billing') === currentBilling) {
                    el.classList.add('btn-primary', 'active');
                    el.classList.remove('btn-outline-secondary');
                } else {
                    el.classList.remove('btn-primary', 'active');
                    el.classList.add('btn-outline-secondary');
                }
            });
            updatePricing();
        });
    });

    modChecks.forEach(function(chk) {
        chk.addEventListener('change', updatePricing);
    });

    updatePricing();
});

document.addEventListener('DOMContentLoaded', function() {
    var stepItems = document.querySelectorAll('.ins-step-item');
    var stepPanes = document.querySelectorAll('.ins-step-pane');
    var nextBtns = document.querySelectorAll('.ins-step-btn-next');
    var prevBtns = document.querySelectorAll('.ins-step-btn-prev');

    function showStep(stepNum) {
        stepPanes.forEach(function(pane) {
            if (pane.getAttribute('data-step') === String(stepNum)) {
                pane.classList.remove('d-none');
                pane.classList.add('active');
            } else {
                pane.classList.add('d-none');
                pane.classList.remove('active');
            }
        });
        stepItems.forEach(function(item) {
            var itemStep = parseInt(item.getAttribute('data-step'));
            var badge = item.querySelector('.ins-step-badge');
            var title = item.querySelector('.ins-step-title');
            if (itemStep === stepNum) {
                item.classList.add('active');
                if (badge) {
                    badge.className = 'ins-step-badge mb-1 text-cyan fw-bold';
                }
                if (title) {
                    title.className = 'ins-step-title text-white fw-bold small';
                }
            } else if (itemStep < stepNum) {
                item.classList.remove('active');
                if (badge) {
                    badge.className = 'ins-step-badge mb-1 text-mint fw-bold';
                }
                if (title) {
                    title.className = 'ins-step-title text-white small';
                }
            } else {
                item.classList.remove('active');
                if (badge) {
                    badge.className = 'ins-step-badge mb-1 text-secondary font-monospace';
                }
                if (title) {
                    title.className = 'ins-step-title text-secondary small';
                }
            }
        });
    }

    nextBtns.forEach(function(btn) {
        btn.addEventListener('click', function() {
            var currentStep = parseInt(this.closest('.ins-step-pane').getAttribute('data-step'));
            var nextStep = parseInt(this.getAttribute('data-next'));
            var currentPane = document.querySelector('.ins-step-pane[data-step="' + currentStep + '"]');
            if (currentPane) {
                var inputs = currentPane.querySelectorAll('input[required], select[required]');
                var allValid = true;
                inputs.forEach(function(input) {
                    if (!input.checkValidity()) {
                        allValid = false;
                        input.reportValidity();
                    }
                });
                if (!allValid) return;
            }
            showStep(nextStep);
        });
    });

    prevBtns.forEach(function(btn) {
        btn.addEventListener('click', function() {
            var prevStep = parseInt(this.getAttribute('data-prev'));
            showStep(prevStep);
        });
    });
});
